public static void onCropGrowth(Level level, BlockPos pos, BlockState state, CallbackInfo ci)
	{
		if (!ModConfig.fertility.seasonalCrops || !ModFertility.isCrop(state))
			return;

		Registry<Block> blockRegistry = level.registryAccess().registryOrThrow(Registries.BLOCK);
		boolean isFertile = ModFertility.isCropFertile(blockRegistry.getKey(state.getBlock()).toString(), level, pos);

		if (!isFertile && !isGlassAboveBlock(level, pos))
		{
			if (ModConfig.fertility.outOfSeasonCropBehavior == 0)
			{
				if (level.getRandom().nextInt(6) != 0)
				{
					ci.cancel();
				}
			}
		    else if (ModConfig.fertility.outOfSeasonCropBehavior == 1)
            {
                ci.cancel();
            }
		    else if (ModConfig.fertility.outOfSeasonCropBehavior == 2)
            {
                if (!state.is(ModTags.Blocks.UNBREAKABLE_INFERTILE_CROPS))
                {
                    level.destroyBlock(pos, false);
                }

				ci.cancel();
            }
		}
	}

public static void applyBonemeal(PlayerInteractEvent.UseBlock event)
	{
		ItemStack stack = event.getItemStack();

		if (stack.getItem() != Items.BONE_MEAL)
			return;

		Player player = event.getPlayer();
		InteractionHand hand = event.getHand();
		Level level = player.level();
		BlockHitResult hitResult = event.getHitResult();
		BlockPos pos = hitResult.getBlockPos();
		BlockState plant = level.getBlockState(pos);
		Block plantBlock = plant.getBlock();
		Registry<Block> blockRegistry = level.registryAccess().registryOrThrow(Registries.BLOCK);

		if (!ModConfig.fertility.seasonalCrops || !ModFertility.isCrop(plant))
			return;

		boolean isFertile = ModFertility.isCropFertile(blockRegistry.getKey(plantBlock).toString(), level, pos);

		if (!isFertile && !isGlassAboveBlock(level, pos))
		{
			if (ModConfig.fertility.outOfSeasonCropBehavior == 0)
			{
				if (level.getRandom().nextInt(6) != 0)
				{
					event.setCancelled(true);
					event.setCancelResult(InteractionResultHolder.success(stack));
				}
			}
            else if (ModConfig.fertility.outOfSeasonCropBehavior == 1)
            {
				event.setCancelled(true);
				event.setCancelResult(InteractionResultHolder.fail(stack));
            }
            else if (ModConfig.fertility.outOfSeasonCropBehavior == 2)
            {
                if (!plant.is(ModTags.Blocks.UNBREAKABLE_INFERTILE_CROPS))
                {
                    level.destroyBlock(pos, false);
					event.setCancelled(true);
					event.setCancelResult(InteractionResultHolder.success(stack));
                }
                else
                {
                    event.setCancelled(true);
                }
            }
		}

		if (event.isCancelled() && !level.isClientSide())
		{
			if (!player.isCreative())
				stack.shrink(1);

			if (stack.isEmpty())
				player.setItemInHand(hand, ItemStack.EMPTY);
		}
	}

private static boolean isGlassAboveBlock(Level world, BlockPos cropPos)
	{
		for (int i = 0; i < 16; i++)
		{
			if (world.getBlockState(cropPos.offset(0, i + 1, 0)).is(ModTags.Blocks.GREENHOUSE_GLASS))
			{
				return true;
			}
		}

		return false;
	}

public Color(int r, int g, int b)
    {
        this.r = r;
        this.g = g;
        this.b = b;
    }

public Color(int color)
    {
        this((color >> 16) & 255, (color >> 8) & 255, color & 255);
    }

public Color(double r, double g, double b)
    {
        this((int)(r * 255.0), (int)(g * 255), (int)(b * 255));
    }

public int getRed()
    {
        return this.r;
    }

public int getGreen()
    {
        return this.g;
    }

public int getBlue()
    {
        return this.b;
    }

public int toInt()
    {
        return (this.getRed() & 255) << 16 | (this.getGreen() & 255) << 8 | this.getBlue() & 255;
    }

public double[] toHSV()
    {
        return convertRGBtoHSV(this.getRed() / 255.0, this.getGreen() / 255.0, this.getBlue() / 255.0);
    }

public static double[] convertRGBtoHSV(double r, double g, double b)
    {
        double h, s, v;
        double min, max, delta;

        min = r < g ? r : g;
        min = min  < b ? min  : b;

        max = r > g ? r : g;
        max = max  > b ? max  : b;

        v = max;
        delta = max - min;
        if (delta < 0.00001)
        {
            s = 0;
            h = 0; // undefined, maybe nan?
            return new double[]{h, s, v};
        }
        if (max > 0.0)
        {
            // NOTE: if Max is == 0, this divide would cause a crash
            s = (delta / max);
        }
        else
        {
            // if max is 0, then r = g = b = 0
            // s = 0, h is undefined
            s = 0.0;
            h = -1.0; // its now undefined
            return new double[]{h, s, v};
        }
        if (r >= max)
            h = ( g - b ) / delta; // between yellow & magenta
        else
        {
            if (g >= max)
                h = 2.0 + (b - r) / delta;  // between cyan & yellow
            else
                h = 4.0 + (r - g) / delta;  // between magenta & cyan
        }

        h *= 60.0;                              // degrees

        if (h < 0.0)
            h += 360.0;

        return new double[]{h, s, v};
    }

public static Color convertHSVtoRGB(double h, double s, double v)
    {
        double hh, p, q, t, ff;
        int i;
        double r, g, b;

        if (s <= 0.0)
        {
            r = v;
            g = v;
            b = v;
            return new Color(r, g, b);
        }
        hh = h;
        if (hh >= 360.0) hh = 0.0;
        hh /= 60.0;
        i = (int)hh;
        ff = hh - i;
        p = v * (1.0 - s);
        q = v * (1.0 - (s * ff));
        t = v * (1.0 - (s * (1.0 - ff)));

        switch (i)
        {
            case 0:
                r = v;
                g = t;
                b = p;
                break;
            case 1:
                r = q;
                g = v;
                b = p;
                break;
            case 2:
                r = p;
                g = v;
                b = t;
                break;

            case 3:
                r = p;
                g = q;
                b = v;
                break;
            case 4:
                r = t;
                g = p;
                b = v;
                break;
            case 5:
            default:
                r = v;
                g = p;
                b = q;
                break;
        }
        return new Color(r, g, b);
    }

public static int multiplyColours(int colour1, int colour2)
    {
        //Convert each colour to a scale between 0 and 1 and multiply them
        //Multiply by 255 to bring back between 0 and 255
        return (int)((colour1 / 255.0F) * (colour2 / 255.0F) * 255.0F);
    }

public static int overlayBlendChannel(int underColour, int overColour)
    {
        int retVal;
        if (underColour < 128)
        {
            retVal = multiplyColours(2 * underColour, overColour);
        }
        else
        {
            retVal = multiplyColours(2 * (255 - underColour), 255 - overColour);
            retVal = 255 - retVal;
        }
        return retVal;
    }

public static int overlayBlend(int underColour, int overColour)
    {
        int r = overlayBlendChannel((underColour >> 16) & 255, (overColour >> 16) & 255);
        int g = overlayBlendChannel((underColour >> 8) & 255, (overColour >> 8) & 255);
        int b = overlayBlendChannel(underColour & 255, overColour & 255);

        return (r & 255) << 16 | (g & 255) << 8 | (b & 255);
    }

public static int mixColours(int a, int b, float ratio) {
        if (ratio > 1f) {
            ratio = 1f;
        } else if (ratio < 0f) {
            ratio = 0f;
        }
        float iRatio = 1.0f - ratio;

        int aA = (a >> 24 & 0xff);
        int aR = ((a & 0xff0000) >> 16);
        int aG = ((a & 0xff00) >> 8);
        int aB = (a & 0xff);

        int bA = (b >> 24 & 0xff);
        int bR = ((b & 0xff0000) >> 16);
        int bG = ((b & 0xff00) >> 8);
        int bB = (b & 0xff);

        int A = (int)((aA * iRatio) + (bA * ratio));
        int R = (int)((aR * iRatio) + (bR * ratio));
        int G = (int)((aG * iRatio) + (bG * ratio));
        int B = (int)((aB * iRatio) + (bB * ratio));

        return A << 24 | R << 16 | G << 8 | B;
    }

public static int saturateColour(int colour, float saturationMultiplier)
    {
        Color newColor = new Color(colour);
        double[] hsv = newColor.toHSV();
        hsv[1] *= saturationMultiplier;
        newColor = Color.convertHSVtoRGB(hsv[0], hsv[1], hsv[2]);
        return newColor.toInt();
    }

public static int applySeasonalGrassColouring(ISeasonColorProvider colorProvider, Holder<Biome> biome, int originalColour)
    {
        ResourceKey<Level> dimension = Minecraft.getInstance().level.dimension();
        if (biome.is(ModTags.Biomes.BLACKLISTED_BIOMES) || !ModConfig.seasons.isDimensionWhitelisted(dimension)) {
            return originalColour;
        }

        int overlay = colorProvider.getGrassOverlay();
        float saturationMultiplier = colorProvider.getGrassSaturationMultiplier();
        if (!ModConfig.seasons.changeGrassColor)
    	{
            overlay = Season.SubSeason.MID_SUMMER.getGrassOverlay();
            saturationMultiplier = Season.SubSeason.MID_SUMMER.getGrassSaturationMultiplier();
    	}
        int newColour = overlay == 0xFFFFFF ? originalColour : overlayBlend(originalColour, overlay);
        int fixedColour = newColour;
        if (biome.is(ModTags.Biomes.LESSER_COLOR_CHANGE_BIOMES))
        {
            fixedColour = mixColours(newColour, originalColour, 0.75F);
        }

        return saturationMultiplier != -1 ? saturateColour(fixedColour, saturationMultiplier) : fixedColour;
    }

public static int applySeasonalFoliageColouring(ISeasonColorProvider colorProvider, Holder<Biome> biome, int originalColour)
    {
        ResourceKey<Level> dimension = Minecraft.getInstance().level.dimension();
        if (biome.is(ModTags.Biomes.BLACKLISTED_BIOMES) || !ModConfig.seasons.isDimensionWhitelisted(dimension))
            return originalColour;

        int overlay = colorProvider.getFoliageOverlay();
        float saturationMultiplier = colorProvider.getFoliageSaturationMultiplier();
        if (!ModConfig.seasons.changeFoliageColor)
    	{
        	overlay = Season.SubSeason.MID_SUMMER.getFoliageOverlay();
            saturationMultiplier = Season.SubSeason.MID_SUMMER.getFoliageSaturationMultiplier();
    	}
        int newColour = overlay == 0xFFFFFF ? originalColour : overlayBlend(originalColour, overlay);
        int fixedColour = newColour;
        if (biome.is(ModTags.Biomes.LESSER_COLOR_CHANGE_BIOMES))
        {
            fixedColour = mixColours(newColour, originalColour, 0.75F);
        }

        return saturationMultiplier != -1 ? saturateColour(fixedColour, saturationMultiplier) : fixedColour;
    }

